const ROOT = '/Users/shunyu/projects/pet-agent-status';
const tj = require(path.join(ROOT, 'lib/terminal-jump.js'));

let n = 0, bad = 0;
const q = [];
function t(name, fn) { q.push({ name, fn }); }

// ---------- 1. detectTerminal 三支（自造 ps 快照，形如真实 ps -eo pid,ppid,tty,comm）----------
function tree(appComm) {
  return [
    { pid: 501, ppid: 1, tty: '??', comm: appComm },
    { pid: 600, ppid: 501, tty: 'ttys007', comm: '/usr/bin/login' },
    { pid: 601, ppid: 600, tty: 'ttys007', comm: '-zsh' },
    { pid: 700, ppid: 601, tty: 'ttys007', comm: '/opt/homebrew/bin/node' }
  ];
}
const ITERM = '/Applications/iTerm.app/Contents/MacOS/iTerm2';
const TERMAPP = '/System/Applications/Utilities/Terminal.app/Contents/MacOS/Terminal';
const VSCODE = '/Applications/Visual Studio Code.app/Contents/MacOS/Electron';

t('detect iterm2', () => assert.strictEqual(tj.detectTerminal('/dev/ttys007', tree(ITERM)), 'iterm2'));
t('detect terminal', () => assert.strictEqual(tj.detectTerminal('/dev/ttys007', tree(TERMAPP)), 'terminal'));
t('detect fallback vscode', () => assert.strictEqual(tj.detectTerminal('/dev/ttys007', tree(VSCODE)), 'activate:Visual Studio Code'));
t('detect null（父链是 code 但非 App 路径）', () =>
  assert.strictEqual(tj.detectTerminal('/dev/ttys007', tree('/usr/local/bin/code')), null));
t('detect null（tty 不在表里）', () =>
  assert.strictEqual(tj.detectTerminal('/dev/ttys099', tree(ITERM)), null));
t('detect 不带 /dev 前缀也认', () =>
  assert.strictEqual(tj.detectTerminal('ttys007', tree(ITERM)), 'iterm2'));

// ppid 成环不死循环
t('ppid 成环返回 null 且不挂起', () => {
  const cyc = [
    { pid: 10, ppid: 11, tty: 'ttys007', comm: 'a' },
    { pid: 11, ppid: 10, tty: 'ttys007', comm: 'b' }
  ];
  assert.strictEqual(tj.detectTerminal('ttys007', cyc), null);
});

// ---------- 2. buildScript 三支：含目标 tty 字面量 + 正确 app 名 ----------
t('iterm2 脚本含 /dev/ttys007 与 iTerm2', () => {
  const s = tj.buildScript('iterm2', '/dev/ttys007');
  assert.ok(s.includes('"/dev/ttys007"'), 'tty 字面量');
  assert.ok(/tell application "iTerm2"/.test(s), 'app 名');
  assert.ok(/sessions of/.test(s) && /select/.test(s) && /activate/.test(s), '精确聚焦');
  assert.ok(!/Terminal/.test(s), '不串台');
});
t('terminal 脚本含 /dev/ttys007 与 Terminal', () => {
  const s = tj.buildScript('terminal', 'ttys007');
  assert.ok(s.includes('"/dev/ttys007"'), 'tty 字面量（归一化补 /dev）');
  assert.ok(/tell application "Terminal"/.test(s));
  assert.ok(/tty of tb is/.test(s));
  assert.ok(!/iTerm/.test(s));
});
t('兜底支只 activate，不出现 tty、不假装精确', () => {
  const s = tj.buildScript('activate:Warp', '/dev/ttys007');
  assert.strictEqual(s, 'tell application "Warp" to activate');
  assert.ok(!s.includes('ttys007'), '兜底不该带 tty');
  assert.ok(!/repeat|select|tty of/.test(s), '兜底不该有精确定位语句');
});
t('null kind → 无脚本（panel 无入口）', () => {
  assert.strictEqual(tj.buildScript(null, '/dev/ttys007'), null);
  assert.strictEqual(tj.scriptForTty('/dev/ttys007', tree('/usr/local/bin/code')), null);
});

// ---------- 3. 注入用例 ----------
const EVIL = [
  `/dev/ttys00'; do evil`,
  `/dev/ttys004" \n tell application "Finder" to activate \n "`,
  `ttys004"; do shell script "rm -rf /"`,
  `../../etc/passwd`,
  `ttys004\ndo shell script "id"`
];
t('恶意 tty 一律拒绝（detect/build/scriptForTty 全 null）', () => {
  for (const e of EVIL) {
    assert.strictEqual(tj.isValidTty(e), false, 'isValidTty ' + JSON.stringify(e));
    assert.strictEqual(tj.detectTerminal(e, tree(ITERM)), null, 'detect ' + JSON.stringify(e));
    assert.strictEqual(tj.buildScript('iterm2', e), null, 'build iterm2 ' + JSON.stringify(e));
    assert.strictEqual(tj.buildScript('terminal', e), null, 'build terminal ' + JSON.stringify(e));
    assert.strictEqual(tj.scriptForTty(e, tree(ITERM)), null);
  }
});
t('恶意 tty 走 runJump 也不执行（runner 必须没被调用）', () => {
  let called = 0;
  const r = tj.runJump(`/dev/ttys00'; do evil`, { psTree: tree(ITERM), runner: () => { called++; return { ok: true }; } });
  assert.strictEqual(called, 0, 'runner 不该被调用');
  assert.strictEqual(r.ok, false);
  assert.strictEqual(r.reason, 'unavailable');
});
t('兜底 App 名是内部常量，生成文本无未转义引号破坏结构', () => {
  const s = tj.buildScript('activate:Visual Studio Code', '');
  assert.strictEqual((s.match(/"/g) || []).length, 2, '恰好一对引号');
});

// ---------- 4. runJump 失败不 throw ----------
t('runner 非零退出 → {ok:false, reason}，不 throw', () => {
  const r = tj.runJump('/dev/ttys007', { psTree: tree(ITERM), runner: () => ({ ok: false, reason: 'osascript: execution error' }) });
  assert.strictEqual(r.ok, false);
  assert.match(r.reason, /execution error/);
  assert.ok(r.script.includes('/dev/ttys007'));
});
t('runner 自己抛异常也被吞成 {ok:false}', () => {
  const r = tj.runJump('/dev/ttys007', { psTree: tree(ITERM), runner: () => { throw new Error('boom'); } });
  assert.strictEqual(r.ok, false);
  assert.match(r.reason, /boom/);
});
t('成功支返回 ok 且带 script/kind', () => {
  const seen = [];
  const r = tj.runJump('/dev/ttys007', { psTree: tree(TERMAPP), runner: (s) => { seen.push(s); return { ok: true }; } });
  assert.strictEqual(r.ok, true);
  assert.strictEqual(r.kind, 'terminal');
  assert.ok(seen[0].includes('"/dev/ttys007"'), '真正交给 runner 的文本含目标 tty');
});

// ---------- 5. 端到端：真实 DOM 点击 → tool 执行 → 失败回推行内错误条 ----------
t('e2e: panel 点击行 → tool 跳转失败 → 该行下方出现 jump-error 错误条', async () => {
  const { JSDOM } = require(path.join(ROOT, 'node_modules/jsdom'));
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'us005-indep-'));
  // 造一个真实协议形态的状态文件（schema:1 必填字段齐全）
  const rec = {
    schema: 1, agent: 'claude-code', sessionId: 'indep-sess-1',
    cwd: '/Users/x/projects/demo', project: 'demo',
    tty: '/dev/ttys007', pid: process.pid, state: 'running',
    lastEvent: 'UserPromptSubmit', ts: Date.now()
  };
  fs.writeFileSync(path.join(dir, 'indep-sess-1.json'), JSON.stringify(rec));

  const dom = new JSDOM(fs.readFileSync(path.join(ROOT, 'panel/panel.html'), 'utf8'),
    { runScripts: 'dangerously', pretendToBeVisual: true });
  const win = dom.window;

  // 事件总线：把 panel 与 tool 真正接起来（不直调内部函数）
  const handlers = { panel: {}, tool: {} };
  const panelPet = {
    events: {
      on: (n2, f) => { handlers.panel[n2] = f; },
      emit: (n2, d) => { if (handlers.tool[n2]) handlers.tool[n2](d); }
    },
    ui: { closePanel: () => {} }
  };
  win.pet = panelPet;
  win.document.dispatchEvent(new win.Event('DOMContentLoaded'));

  let jumpAttempts = 0;
  const toolPet = {
    events: {
      on: (n2, f) => { handlers.tool[n2] = f; },
      emit: (n2, d) => { if (handlers.panel[n2]) handlers.panel[n2](d); }
    },
    scheduler: { every: async () => 'task-1', cancel: async () => {} },
    pet: { bubble: () => {}, playAnim: () => {}, speak: () => {} },
    storage: { get: async () => null, set: async () => {} }
  };
  const createCollector = require(path.join(ROOT, 'tool/index.js')).__test.createCollector;
  const collector = createCollector({
    dir,
    psTree: tree(ITERM),                       // 伪造进程表：这条 tty 归 iTerm2
    jumpRunner: () => { jumpAttempts++; return { ok: false, reason: 'osascript: application isn\'t running' }; },
    isPidAlive: () => true,
    claudeSettings: path.join(dir, 'settings.json')
  });
  await collector.start(toolPet);

  const rowEl = win.document.querySelector('.row');
  assert.ok(rowEl, '应渲染出一行');
  assert.ok(rowEl.classList.contains('can-jump'), 'iTerm2 归属的行应为可点态');
  assert.strictEqual(win.document.querySelector('.jump-error'), null, '点击前不该有错误条');

  // 真实 DOM 点击事件（非直调 handler）
  rowEl.dispatchEvent(new win.MouseEvent('click', { bubbles: true }));

  assert.strictEqual(jumpAttempts, 1, 'tool 应实际尝试执行一次跳转');
  const err = win.document.querySelector('.jump-error');
  assert.ok(err, '失败后应出现行内错误条');
  assert.ok(/isn't running|执行失败|failed/i.test(err.textContent), '错误条含原因: ' + err.textContent);
  assert.strictEqual(err.dataset.sessionId, 'indep-sess-1');
  // 错误条紧跟在该行之后
  assert.strictEqual(rowEl.nextElementSibling, err, '错误条应紧挨该行下方');
  // 不是弹窗
  assert.ok(!/alert|confirm/.test(fs.readFileSync(path.join(ROOT, 'panel/panel.html'), 'utf8')), 'panel 不该用弹窗');

  await collector.stop(toolPet);
  fs.rmSync(dir, { recursive: true, force: true });
});

t('e2e: 推断不出终端的行不可点、无 click handler', async () => {
  const { JSDOM } = require(path.join(ROOT, 'node_modules/jsdom'));
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'us005-indep2-'));
  fs.writeFileSync(path.join(dir, 'indep-sess-2.json'), JSON.stringify({
    schema: 1, agent: 'claude-code', sessionId: 'indep-sess-2',
    cwd: '/Users/x/projects/demo2', project: 'demo2',
    tty: '/dev/ttys007', pid: process.pid, state: 'running',
    lastEvent: 'UserPromptSubmit', ts: Date.now()
  }));
  const dom = new JSDOM(fs.readFileSync(path.join(ROOT, 'panel/panel.html'), 'utf8'),
    { runScripts: 'dangerously', pretendToBeVisual: true });
  const win = dom.window;
  const handlers = { panel: {}, tool: {} };
  win.pet = {
    events: { on: (n2, f) => { handlers.panel[n2] = f; }, emit: (n2, d) => { if (handlers.tool[n2]) handlers.tool[n2](d); } },
    ui: { closePanel: () => {} }
  };
  win.document.dispatchEvent(new win.Event('DOMContentLoaded'));
  let attempts = 0;
  const toolPet = {
    events: { on: (n2, f) => { handlers.tool[n2] = f; }, emit: (n2, d) => { if (handlers.panel[n2]) handlers.panel[n2](d); } },
    scheduler: { every: async () => 'x', cancel: async () => {} },
    pet: { bubble: () => {}, playAnim: () => {}, speak: () => {} },
    storage: { get: async () => null, set: async () => {} }
  };
  const createCollector = require(path.join(ROOT, 'tool/index.js')).__test.createCollector;
  const collector = createCollector({
    dir,
    psTree: tree('/usr/local/bin/code'),   // 认不出终端
    jumpRunner: () => { attempts++; return { ok: true }; },
    isPidAlive: () => true,
    claudeSettings: path.join(dir, 'settings.json')
  });
  await collector.start(toolPet);
  const rowEl = win.document.querySelector('.row');
  assert.ok(rowEl, '行仍应渲染');
  assert.ok(!rowEl.classList.contains('can-jump'), '不该是可点态');
  rowEl.dispatchEvent(new win.MouseEvent('click', { bubbles: true }));
  assert.strictEqual(attempts, 0, '不可点的行点了不该触发跳转');
  await collector.stop(toolPet);
  fs.rmSync(dir, { recursive: true, force: true });
});

// ---------- 6. 判定单处：panel/aggregate 不得自己判终端 ----------
t('归属判定只在 lib/terminal-jump.js（panel/aggregate 无 iTerm/Terminal.app 判定）', () => {
  const panelSrc = fs.readFileSync(path.join(ROOT, 'panel/panel.html'), 'utf8');
  const aggSrc = fs.readFileSync(path.join(ROOT, 'lib/aggregate.js'), 'utf8');
  for (const [n2, src] of [['panel', panelSrc], ['aggregate', aggSrc]]) {
    assert.ok(!/iTerm|Terminal\.app|osascript|tell application/i.test(src), n2 + ' 不该含终端判定/脚本');
  }
});

(async () => {
  for (const { name, fn } of q) {
    try { await fn(); n++; console.log('  ok  ' + name); }
    catch (e) { bad++; console.log('  FAIL ' + name + '\n       ' + e.message); }
  }
  console.log('\n' + n + ' passed, ' + bad + ' failed');
  process.exit(bad ? 1 : 0);
})();

