t('e2e: 推断不出终端的行不可点、无 click handler', async () => {
  const { JSDOM } = require(path.join(ROOT, 'node_modules/jsdom'));
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'us005-indep2-'));
  fs.writeFileSync(path.join(dir, 'indep-sess-2.json'), JSON.stringify({
    schema: 1, agent: 'claude-code', sessionId: 'indep-sess-2',
    cwd: '/Users/x/projects/demo2', project: 'demo2',
    tty: '/dev/ttys007', pid: process.pid, state: 'running',
    lastEvent: 'UserPromptSubmit', ts: Date.now()
  }));
  const dom = new JSDOM(fs.readFileSync(path.join(ROOT, 'panel/panel.html'), 'utf8'),
    { runScripts: 'dangerously', pretendToBeVisual: true });
  const win = dom.window;
  const handlers = { panel: {}, tool: {} };
  win.pet = {
    events: { on: (n2, f) => { handlers.panel[n2] = f; }, emit: (n2, d) => { if (handlers.tool[n2]) handlers.tool[n2](d); } },
    ui: { closePanel: () => {} }
  };
  win.document.dispatchEvent(new win.Event('DOMContentLoaded'));
  let attempts = 0;
  const toolPet = {
    events: { on: (n2, f) => { handlers.tool[n2] = f; }, emit: (n2, d) => { if (handlers.panel[n2]) handlers.panel[n2](d); } },
    scheduler: { every: async () => 'x', cancel: async () => {} },
    pet: { bubble: () => {}, playAnim: () => {}, speak: () => {} },
    storage: { get: async () => null, set: async () => {} }
  };
  const createCollector = require(path.join(ROOT, 'tool/index.js')).__test.createCollector;
  const collector = createCollector({
    dir,
    psTree: tree('/usr/local/bin/code'),   // 认不出终端
    jumpRunner: () => { attempts++; return { ok: true }; },
    isPidAlive: () => true,
    claudeSettings: path.join(dir, 'settings.json')
  });
